import React from 'react';
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from 'chart.js';
import { Doughnut } from 'react-chartjs-2';
import { ShieldCheck, AlertTriangle, Cpu, Wrench, Sparkles, CheckCircle } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

ChartJS.register(ArcElement, Tooltip, Legend);

const CriticalityChart = ({ high = 0, medium = 0, low = 0 }) => {
  const navigate = useNavigate();
  const total = high + medium + low || 1;
  const highPct = Math.round((high / total) * 100);
  const mediumPct = Math.round((medium / total) * 100);
  const lowPct = Math.round((low / total) * 100);

  const data = {
    labels: [`High (${highPct}%)`, `Medium (${mediumPct}%)`, `Low (${lowPct}%)`],
    datasets: [
      {
        data: [high, medium, low],
        backgroundColor: ['#8B5CF6', '#F59E0B', '#38BDF8'],
        borderColor: ['#ffffff', '#ffffff', '#ffffff'],
        borderWidth: 3,
        hoverOffset: 8,
      },
    ],
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'bottom',
        labels: {
          color: 'var(--text-primary)',
          font: { family: 'Plus Jakarta Sans', size: 12, weight: '800' },
          usePointStyle: true,
          boxWidth: 8,
          padding: 12,
        },
      },
      tooltip: {
        backgroundColor: '#0F172A',
        titleColor: '#FFFFFF',
        bodyColor: '#E2E8F0',
        borderColor: '#E2E8F0',
        borderWidth: 1,
      },
    },
    cutout: '62%',
  };

  // High risk watchlist items with AI Diagnostic recommendations
  const watchlist = [
    {
      machineId: 'LOOM-201',
      name: 'Dornier Heavy Shuttleless',
      health: 68,
      recommendation: 'Drive shaft bearing fatigue. Replace within 14 hrs.',
    },
    {
      machineId: 'LOOM-104',
      name: 'Tsudakoma Water Jet',
      health: 88,
      recommendation: 'Nozzle scale build-up detected. Flush cycle needed.',
    },
  ];

  return (
    <div className="glass-card" style={{ padding: '1.5rem', display: 'flex', flexDirection: 'column', height: '100%' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.75rem' }}>
        <h3 style={{ fontSize: '1.05rem', fontWeight: '800', color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <ShieldCheck size={18} style={{ color: 'var(--status-critical)' }} /> Criticality Distribution
        </h3>
        <span className="badge badge-high" style={{ fontWeight: '800' }}>AI Risk Index</span>
      </div>

      {/* Prominent Donut Chart Canvas */}
      <div style={{ height: '240px', width: '100%', position: 'relative' }}>
        <Doughnut data={data} options={options} />
        {/* Center Donut Metric Counter */}
        <div
          style={{
            position: 'absolute',
            top: '38%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            textAlign: 'center',
            pointerEvents: 'none',
          }}
        >
          <div style={{ fontSize: '2.5rem', fontWeight: '900', color: 'var(--status-critical)', lineHeight: 1 }}>{high}</div>
          <div style={{ fontSize: '0.75rem', fontWeight: '800', color: 'var(--text-muted)', marginTop: '4px', letterSpacing: '0.5px' }}>
            HIGH RISK
          </div>
        </div>
      </div>

      {/* Filled Free Area: High-Risk Watchlist & AI Diagnostic Recommendations */}
      <div
        style={{
          background: 'var(--status-critical-bg)',
          border: '1px solid rgba(139, 92, 246, 0.25)',
          borderRadius: 'var(--radius-sm)',
          padding: '0.85rem',
          marginTop: '0.75rem',
          display: 'flex',
          flexDirection: 'column',
          gap: '0.6rem',
        }}
      >
        <div style={{ fontSize: '0.78rem', fontWeight: '800', color: 'var(--status-critical)', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <span style={{ display: 'flex', alignItems: 'center', gap: '0.35rem' }}>
            <AlertTriangle size={14} /> HIGH-RISK WATCHLIST & AI DIAGNOSTICS
          </span>
          <span style={{ fontSize: '0.7rem', opacity: 0.8 }}>2 Looms Flagged</span>
        </div>

        {watchlist.map((item) => (
          <div
            key={item.machineId}
            style={{
              display: 'flex',
              flexDirection: 'column',
              gap: '0.2rem',
              background: 'var(--bg-card)',
              border: '1px solid var(--border-subtle)',
              padding: '0.5rem 0.65rem',
              borderRadius: '6px',
            }}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '0.82rem', fontWeight: '800', color: 'var(--text-primary)' }}>
              <div>
                <span style={{ color: 'var(--accent-primary)', fontFamily: 'JetBrains Mono', marginRight: '6px' }}>{item.machineId}</span>
                <span>{item.name}</span>
              </div>
              <span style={{ color: item.health < 80 ? 'var(--status-maintenance)' : 'var(--status-idle)', fontWeight: '800' }}>
                {item.health}% Health
              </span>
            </div>
            <div style={{ fontSize: '0.74rem', color: 'var(--text-secondary)', display: 'flex', alignItems: 'center', gap: '0.35rem', fontWeight: '600' }}>
              <Sparkles size={12} style={{ color: 'var(--status-critical)', flexShrink: 0 }} />
              <span>{item.recommendation}</span>
            </div>
          </div>
        ))}
      </div>

      {/* AI Action Trigger Footer to completely fill bottom space */}
      <div style={{ marginTop: '0.75rem', display: 'flex', gap: '0.5rem' }}>
        <button
          onClick={() => navigate('/what-if')}
          className="btn btn-secondary btn-sm"
          style={{ flex: 1, justifyContent: 'center', fontSize: '0.76rem', fontWeight: '700' }}
        >
          <Cpu size={14} style={{ color: 'var(--accent-primary)' }} /> Run AI Simulation
        </button>
        <button
          onClick={() => navigate('/assets')}
          className="btn btn-primary btn-sm"
          style={{ flex: 1, justifyContent: 'center', fontSize: '0.76rem', fontWeight: '700' }}
        >
          <Wrench size={14} /> Schedule Repair
        </button>
      </div>
    </div>
  );
};

export default CriticalityChart;
